template <typename T>
void process(const T& item) {
    // Compiler treats const T& internally like T* (Pointer)
    // Argument slot size: sizeof(void*) (e.g., 8 bytes)
    // Instantiation cost incurred per unique T
}

struct LargeData { char buffer[512]; };

void caller() {
    int i = 1;
    LargeData d;

    process(i); // Instantiate process<int>
    process(d); // Instantiate process<LargeData>
                // Argument passing is cheap (fixed pointer size)
}

// Result: Template bloat is possible, but runtime argument cost is minimal.
